```tsx
// AccountSettingsScreen.tsx
import React, { useCallback, useState } from 'react';
import {
  ActivityIndicator,
  Alert,
  Image,
  Modal,
  Platform,
  Pressable,
  ScrollView,
  StatusBar,
  StyleSheet,
  Switch,
  Text,
  View,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context'; // falls back below if not installed

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

type NavigationLike = {
  navigate: (screen: string, params?: Record<string, unknown>) => void;
};

interface UserProfile {
  name: string;
  email: string;
  avatarUrl?: string;
}

interface SettingsRowBase {
  key: string;
  label: string;
  icon: string; // emoji placeholder so this file has zero icon-lib dependency
}

interface NavigationRow extends SettingsRowBase {
  type: 'navigation';
  value?: string;
  onPress: () => void;
}

interface ToggleRow extends SettingsRowBase {
  type: 'toggle';
  value: boolean;
  onValueChange: (next: boolean) => void;
}

type SettingsRow = NavigationRow | ToggleRow;

interface SettingsSection {
  title?: string;
  rows: SettingsRow[];
}

// ---------------------------------------------------------------------------
// Profile row
// ---------------------------------------------------------------------------

function ProfileRow({
  profile,
  onPress,
}: {
  profile: UserProfile;
  onPress: () => void;
}) {
  const initials = profile.name
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join('');

  return (
    <Pressable
      onPress={onPress}
      accessibilityRole="button"
      accessibilityLabel={`Edit profile, ${profile.name}`}
      style={({ pressed }) => [
        styles.profileRow,
        pressed && Platform.OS === 'ios' && { opacity: 0.6 },
      ]}
      android_ripple={{ color: '#D0D0D0' }}
    >
      {profile.avatarUrl ? (
        <Image source={{ uri: profile.avatarUrl }} style={styles.avatar} />
      ) : (
        <View style={[styles.avatar, styles.avatarFallback]}>
          <Text style={styles.avatarInitials}>{initials || '?'}</Text>
        </View>
      )}

      <View style={styles.profileText}>
        <Text style={styles.profileName} numberOfLines={1}>
          {profile.name}
        </Text>
        <Text style={styles.profileEmail} numberOfLines={1}>
          {profile.email}
        </Text>
      </View>

      <Text style={styles.chevron}>›</Text>
    </Pressable>
  );
}

// ---------------------------------------------------------------------------
// Generic settings row
// ---------------------------------------------------------------------------

function SettingsRowItem({ row }: { row: SettingsRow }) {
  if (row.type === 'toggle') {
    return (
      <View style={styles.row} accessibilityRole="none">
        <Text style={styles.rowIcon}>{row.icon}</Text>
        <Text style={styles.rowLabel}>{row.label}</Text>
        <Switch
          value={row.value}
          onValueChange={row.onValueChange}
          accessibilityRole="switch"
          accessibilityLabel={row.label}
          accessibilityState={{ checked: row.value }}
        />
      </View>
    );
  }

  return (
    <Pressable
      onPress={row.onPress}
      accessibilityRole="button"
      accessibilityLabel={row.label}
      style={({ pressed }) => [
        styles.row,
        pressed && Platform.OS === 'ios' && { opacity: 0.6 },
      ]}
      android_ripple={{ color: '#D0D0D0' }}
    >
      <Text style={styles.rowIcon}>{row.icon}</Text>
      <Text style={styles.rowLabel}>{row.label}</Text>
      {row.value ? <Text style={styles.rowValue}>{row.value}</Text> : null}
      <Text style={styles.chevron}>›</Text>
    </Pressable>
  );
}

function Section({ section }: { section: SettingsSection }) {
  return (
    <View style={styles.section}>
      {section.title ? (
        <Text style={styles.sectionTitle}>{section.title}</Text>
      ) : null}
      <View style={styles.sectionCard}>
        {section.rows.map((row, index) => (
          <View key={row.key}>
            <SettingsRowItem row={row} />
            {index < section.rows.length - 1 ? (
              <View style={styles.separator} />
            ) : null}
          </View>
        ))}
      </View>
    </View>
  );
}

// ---------------------------------------------------------------------------
// Delete account confirmation modal
// ---------------------------------------------------------------------------

function DeleteAccountModal({
  visible,
  onCancel,
  onConfirm,
  isDeleting,
}: {
  visible: boolean;
  onCancel: () => void;
  onConfirm: () => void;
  isDeleting: boolean;
}) {
  return (
    <Modal
      visible={visible}
      transparent
      animationType="fade"
      onRequestClose={() => {
        // Android hardware back button
        if (!isDeleting) onCancel();
      }}
    >
      <View style={styles.modalOverlay}>
        <View style={styles.modalCard}>
          <Text style={styles.modalTitle}>Delete your account?</Text>
          <Text style={styles.modalBody}>
            This permanently deletes your profile, settings, and data. This
            action can't be undone.
          </Text>

          <Pressable
            onPress={onConfirm}
            disabled={isDeleting}
            accessibilityRole="button"
            accessibilityLabel="Confirm delete account"
            style={({ pressed }) => [
              styles.modalButton,
              styles.modalButtonDestructive,
              pressed && { opacity: 0.8 },
              isDeleting && { opacity: 0.6 },
            ]}
          >
            {isDeleting ? (
              <ActivityIndicator color="#FFFFFF" />
            ) : (
              <Text style={styles.modalButtonDestructiveText}>
                Delete Account
              </Text>
            )}
          </Pressable>

          <Pressable
            onPress={onCancel}
            disabled={isDeleting}
            accessibilityRole="button"
            accessibilityLabel="Cancel"
            style={({ pressed }) => [
              styles.modalButton,
              pressed && { opacity: 0.6 },
            ]}
          >
            <Text style={styles.modalButtonCancelText}>Cancel</Text>
          </Pressable>
        </View>
      </View>
    </Modal>
  );
}

