async function deleteAccountRequest(): Promise<void> {
  // Replace with real API call, e.g.:
  // await api.delete('/me');
  await new Promise<void>((resolve, reject) =>
    setTimeout(() => {
      // Simulated success; reject(new Error('...')) to exercise the error path.
      resolve();
    }, 1200),
  );
}

