          label: 'Security',
          onPress: () => navigation.navigate('Security'),
        },
        {
          type: 'navigation',
          key: 'privacy',
          icon: '🕵️',
          label: 'Privacy',
          onPress: () => navigation.navigate('Privacy'),
        },
        {
          type: 'navigation',
